ScrollView {
    VStack(alignment: .leading, spacing: theme.spacing.space4) {
        VStack(alignment: .leading, spacing: theme.spacing.space1) {
            Text({{title}}).monarchTextStyle(.title)
            Text({{description}}).monarchTextStyle(.body).foregroundStyle(theme.colors.textMuted)
        }
        ScrollView(.horizontal, showsIndicators: false) {
            HStack(spacing: theme.spacing.space2) {
                MonarchPeriodSelector(selection: $period, today: {{today|date}})
                MonarchButton({{arrange}}, variant: .secondary, size: .sm) { isArranging.toggle() }
            }
        }
        HStack(alignment: .top, spacing: theme.spacing.space2) {
                MonarchStatCard({{kpis.0.label}}, value: {{kpis.0.value|double}})
                MonarchStatCard({{kpis.1.label}}, value: {{kpis.1.value|double}}, format: .currency(code: {{kpis.1.currency}}), isCompact: {{kpis.1.compact}})
                MonarchStatCard({{kpis.2.label}}, value: {{kpis.2.value|double}})
        }
        MonarchInsightStrip(
            {{headings.insights}},
            insights: [
                MonarchInsight(
                    id: {{insight.id}},
                    title: {{insight.title}},
                    why: {{insight.why}},
                    tone: {{insight.severity|tone}},
                    origin: {{insight.origin|case}},
                    actionTitle: {{insight.action}},
                    action: {}
                )
            ],
            layout: .stack
        )
        MonarchDashboardGrid(
            tiles,
            layout: $layout,
            itemLabel: \.title,
            isEditing: isArranging,
            content: { tile in section(tile) }
        )
    }
    .padding(theme.spacing.space4)
}
.environment(\.locale, Locale(identifier: {{locale}}))
.frame(maxWidth: .infinity, minHeight: theme.spacing.space24 * 6)

