@Environment(\.monarchTheme) private var theme
@State private var layout: [String] = []
@State private var period = MonarchPeriod(.last7Days)
@State private var isArranging = false

/// One section of the home screen.
struct Tile: Identifiable {
    let id: String
    let title: String
}

private let tiles = [
    Tile(id: "composition", title: {{headings.composition}}),
    Tile(id: "attention", title: {{headings.attention}}),
    Tile(id: "upcoming", title: {{headings.upcoming}}),
    Tile(id: "breakdown", title: {{headings.breakdown}}),
    Tile(id: "ranking", title: {{headings.ranking}}),
    Tile(id: "activity", title: {{headings.activity}}),
]
private let now = {{now|date}}

@ViewBuilder private func section(_ tile: Tile) -> some View {
    switch tile.id {
    case "composition":
        MonarchWidget(tile.title, variant: .plain) {
            MonarchDonutChart(
                {{composition.title}},
                segments: [
                    MonarchDonutChartSegment({{composition.segments.0.key}}, label: {{composition.segments.0.label}}, value: {{composition.segments.0.value|double}}),
                    MonarchDonutChartSegment({{composition.segments.1.key}}, label: {{composition.segments.1.label}}, value: {{composition.segments.1.value|double}}),
                    MonarchDonutChartSegment({{composition.segments.2.key}}, label: {{composition.segments.2.label}}, value: {{composition.segments.2.value|double}}),
                    MonarchDonutChartSegment({{composition.segments.3.key}}, label: {{composition.segments.3.label}}, value: {{composition.segments.3.value|double}}),
                ],
                centerValue: {{composition.centerValue}},
                centerLabel: {{composition.centerLabel}}
            )
        }
    case "attention":
        MonarchWidget(tile.title, variant: .plain) {
            VStack(alignment: .leading, spacing: theme.spacing.space3) {
                LabeledContent({{attention.0.label}}) { MonarchBadge({{attention.0.badge}}, tone: {{attention.0.tone|tone}}) }
                LabeledContent({{attention.1.label}}) { MonarchBadge({{attention.1.badge}}, tone: {{attention.1.tone|tone}}) }
            }
            .labeledContentStyle(.monarch(.inline))
        }
    case "upcoming":
        MonarchWidget(tile.title, variant: .plain) {
            VStack(alignment: .leading, spacing: theme.spacing.space3) {
                LabeledContent({{upcoming.0.label}}, value: {{upcoming.0.value}})
                LabeledContent({{upcoming.1.label}}, value: {{upcoming.1.value}})
                LabeledContent({{upcoming.2.label}}, value: {{upcoming.2.value}})
            }
            .labeledContentStyle(.monarch(.inline))
        }
    case "breakdown":
        MonarchWidget(tile.title, variant: .plain) {
            MonarchBarList(
                {{breakdown.label}},
                items: [
                    MonarchBarListItem({{breakdown.items.0.label}}, id: {{breakdown.items.0.id}}, value: {{breakdown.items.0.value|double}}),
                    MonarchBarListItem({{breakdown.items.1.label}}, id: {{breakdown.items.1.id}}, value: {{breakdown.items.1.value|double}}),
                    MonarchBarListItem({{breakdown.items.2.label}}, id: {{breakdown.items.2.id}}, value: {{breakdown.items.2.value|double}}),
                    MonarchBarListItem({{breakdown.items.3.label}}, id: {{breakdown.items.3.id}}, value: {{breakdown.items.3.value|double}}),
                ]
            )
        }
    case "ranking":
        MonarchWidget(tile.title, variant: .plain) {
            MonarchLeaderboard(
                [
                    MonarchLeaderboardEntry({{ranking.entries.0.name}}, value: {{ranking.entries.0.value|double}}, id: {{ranking.entries.0.id}}, display: {{ranking.entries.0.display}}),
                    MonarchLeaderboardEntry({{ranking.entries.1.name}}, value: {{ranking.entries.1.value|double}}, id: {{ranking.entries.1.id}}, display: {{ranking.entries.1.display}}),
                    MonarchLeaderboardEntry({{ranking.entries.2.name}}, value: {{ranking.entries.2.value|double}}, id: {{ranking.entries.2.id}}, display: {{ranking.entries.2.display}}),
                ],
                valueLabel: {{ranking.valueLabel}},
                showsAvatars: false
            )
        }
    default:
        MonarchWidget(tile.title, variant: .plain) {
            MonarchActivityTimeline(
                [
                    MonarchActivityTimelineEvent(id: {{events.0.id}}, actor: MonarchActivityTimelineActor({{events.0.actor}}), verb: {{events.0.verb}}, object: {{events.0.object}}, time: {{events.0.time|date}}),
                    MonarchActivityTimelineEvent(id: {{events.1.id}}, actor: MonarchActivityTimelineActor({{events.1.actor}}), verb: {{events.1.verb}}, object: {{events.1.object}}, time: {{events.1.time|date}}),
                ],
                isGroupedByDay: false,
                density: .compact,
                now: now
            )
        }
    }
}

