@Environment(\.monarchTheme) private var theme
@State private var layout: [String] = []
@State private var period = MonarchPeriod(.last7Days)
@State private var isArranging = false

/// One section of the home screen.
struct Tile: Identifiable {
    let id: String
    let title: String
}

private let tiles = [
    Tile(id: "composition", title: "Composition"),
    Tile(id: "attention", title: "Needs attention"),
    Tile(id: "upcoming", title: "Coming up"),
    Tile(id: "breakdown", title: "Breakdown"),
    Tile(id: "ranking", title: "Top items"),
    Tile(id: "activity", title: "Recent activity"),
]
private let now = Date(timeIntervalSince1970: 1_781_517_600)

@ViewBuilder private func section(_ tile: Tile) -> some View {
    switch tile.id {
    case "composition":
        MonarchWidget(tile.title, variant: .plain) {
            MonarchDonutChart(
                "Contracts by type",
                segments: [
                    MonarchDonutChartSegment("software", label: "Software", value: 28.0),
                    MonarchDonutChartSegment("services", label: "Services", value: 19.0),
                    MonarchDonutChartSegment("facilities", label: "Facilities", value: 11.0),
                    MonarchDonutChartSegment("hardware", label: "Hardware", value: 6.0),
                ],
                centerValue: "64",
                centerLabel: "contracts"
            )
        }
    case "attention":
        MonarchWidget(tile.title, variant: .plain) {
            VStack(alignment: .leading, spacing: theme.spacing.space3) {
                LabeledContent("Cleaning services, Leeds") { MonarchBadge("No owner", tone: .danger) }
                LabeledContent("Laptop leasing") { MonarchBadge("No end date", tone: .warning) }
            }
            .labeledContentStyle(.monarch(.inline))
        }
    case "upcoming":
        MonarchWidget(tile.title, variant: .plain) {
            VStack(alignment: .leading, spacing: theme.spacing.space3) {
                LabeledContent("Office lease, York", value: "1 Jul 2026")
                LabeledContent("CRM licences", value: "14 Jul 2026")
                LabeledContent("Cleaning services, Leeds", value: "31 Jul 2026")
            }
            .labeledContentStyle(.monarch(.inline))
        }
    case "breakdown":
        MonarchWidget(tile.title, variant: .plain) {
            MonarchBarList(
                "Contracts by location",
                items: [
                    MonarchBarListItem("London", id: "london", value: 31.0),
                    MonarchBarListItem("Leeds", id: "leeds", value: 18.0),
                    MonarchBarListItem("York", id: "york", value: 9.0),
                    MonarchBarListItem("Remote", id: "remote", value: 6.0),
                ]
            )
        }
    case "ranking":
        MonarchWidget(tile.title, variant: .plain) {
            MonarchLeaderboard(
                [
                    MonarchLeaderboardEntry("Office lease, London", value: 420_000.0, id: "lease", display: "£420k"),
                    MonarchLeaderboardEntry("CRM licences", value: 186_000.0, id: "crm", display: "£186k"),
                    MonarchLeaderboardEntry("Cleaning services", value: 74_000.0, id: "cleaning", display: "£74k"),
                ],
                valueLabel: "Annual value",
                showsAvatars: false
            )
        }
    default:
        MonarchWidget(tile.title, variant: .plain) {
            MonarchActivityTimeline(
                [
                    MonarchActivityTimelineEvent(id: "e1", actor: MonarchActivityTimelineActor("Mei Chen"), verb: "renewed", object: "Payroll software", time: Date(timeIntervalSince1970: 1_781_516_400)),
                    MonarchActivityTimelineEvent(id: "e2", actor: MonarchActivityTimelineActor("Lucas Martin"), verb: "added", object: "Laptop leasing", time: Date(timeIntervalSince1970: 1_781_510_700)),
                ],
                isGroupedByDay: false,
                density: .compact,
                now: now
            )
        }
    }
}

